12	interface AuthFormProps {
13	  defaultTab?: "signin" | "signup";
14	  onSuccess?: () => void;
15	}
16	
17	const AuthForm = ({ defaultTab = "signin", onSuccess }: AuthFormProps) => {
18	  const [email, setEmail] = useState("");
19	  const [password, setPassword] = useState("");
20	  const [confirmPassword, setConfirmPassword] = useState("");
21	  const [loading, setLoading] = useState(false);
22	
23	  const handleSignUp = async (e: React.FormEvent) => {
24	    e.preventDefault();
25	    if (password !== confirmPassword) {
26	      toast.error("Passwords do not match");
27	      return;
28	    }
29	    setLoading(true);
30	    try {
31	      const { error } = await supabase.auth.signUp({
32	        email,
33	        password,
34	        options: { emailRedirectTo: window.location.origin },
35	      });
36	      if (error) {
37	        toast.error(error.message);
38	      } else {
39	        toast.success("Check your email to confirm your account!");
40	        onSuccess?.();
41	      }
42	    } catch (err) {
43	      console.error("Unexpected sign-up error:", err);
44	      toast.error("An unexpected error occurred. Please try again.");
45	    } finally {
46	      setLoading(false);
47	    }
48	  };
49	
50	  const handleSignIn = async (e: React.FormEvent) => {
51	    e.preventDefault();
52	    setLoading(true);
53	    try {
54	      const { error } = await supabase.auth.signInWithPassword({ email, password });
55	      if (error) {
56	        toast.error(error.message);
57	      } else {
58	        toast.success("Signed in successfully");
59	        onSuccess?.();
60	      }
61	    } catch (err) {
62	      console.error("Unexpected sign-in error:", err);
63	      toast.error("An unexpected error occurred. Please try again.");
64	    } finally {
65	      setLoading(false);
66	    }
67	  };
68	
69	  const handleMagicLink = async () => {
70	    if (!email) {
71	      toast.error("Enter your email first");
72	      return;
73	    }
74	    setLoading(true);
75	    try {
76	      const { error } = await supabase.auth.signInWithOtp({
77	        email,
78	        options: { emailRedirectTo: window.location.origin },
79	      });
80	      if (error) toast.error(error.message);
81	      else toast.success("Magic link sent! Check your email.");
82	    } catch (err) {
83	      console.error("Unexpected magic link error:", err);
84	      toast.error("An unexpected error occurred. Please try again.");
85	    } finally {
86	      setLoading(false);
87	    }
88	  };
89	
90	  return (
91	    <Tabs defaultValue={defaultTab} className="w-full">
92	      <TabsList className="grid w-full grid-cols-2 mb-6">
93	        <TabsTrigger value="signin">Sign In</TabsTrigger>
94	        <TabsTrigger value="signup">Sign Up</TabsTrigger>
95	      </TabsList>
96	      <TabsContent value="signin">
97	        <form onSubmit={handleSignIn} className="space-y-4">
98	          <div className="space-y-2">
99	            <Label htmlFor="signin-email">Email <span className="text-destructive">*</span></Label>
100	            <Input id="signin-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@company.com" required />
101	          </div>
102	          <div className="space-y-2">
103	            <Label htmlFor="signin-password">Password <span className="text-destructive">*</span></Label>
104	            <Input id="signin-password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" required />
105	          </div>
106	          <Button type="submit" className="w-full" disabled={loading}>
107	            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
108	            Sign In
109	          </Button>
110	          <Button type="button" variant="outline" className="w-full" onClick={handleMagicLink} disabled={loading}>
111	            Send Magic Link
112	          </Button>
113	        </form>
114	      </TabsContent>
115	      <TabsContent value="signup">
116	        <form onSubmit={handleSignUp} className="space-y-4">
117	          <div className="space-y-2">
118	            <Label htmlFor="signup-email">Email <span className="text-destructive">*</span></Label>
119	            <Input id="signup-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@company.com" required />
120	          </div>
121	          <div className="space-y-2">
122	            <Label htmlFor="signup-password">Password <span className="text-destructive">*</span></Label>
123	            <Input id="signup-password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Min 6 characters" required minLength={6} />
124	            <p className="text-xs text-muted-foreground">At least 6 characters required</p>
125	          </div>
126	          <div className="space-y-2">
127	            <Label htmlFor="signup-confirm-password">Confirm Password <span className="text-destructive">*</span></Label>
128	            <Input id="signup-confirm-password" type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} placeholder="Repeat password" required minLength={6} />
129	            {confirmPassword && password !== confirmPassword && (
130	              <p className="text-xs text-destructive">Passwords do not match</p>
131	            )}
132	          </div>
133	          <Button type="submit" className="w-full" disabled={loading || (!!confirmPassword && password !== confirmPassword)}>
134	            {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
135	            Create Account
136	          </Button>
137	        </form>
138	      </TabsContent>
139	    </Tabs>
