1	"use client";
2	
3	import { useState, useEffect, createContext, useContext, useRef } from "react";
4	import { supabase } from "@/integrations/supabase/browser";
5	import type { User, Session } from "@supabase/supabase-js";
6	
7	type Profile = {
8	  credits: number;
9	  subscription_credits: number;
10	  topup_credits: number;
11	  bonus_credits: number;
12	  inbox_email: string | null;
13	  plan: string;
14	  email_enabled: boolean;
15	  auto_rank_enabled: boolean;
16	  subscription_ends_at: string | null;
17	};
18	
19	interface AuthContextType {
20	  user: User | null;
21	  session: Session | null;
22	  loading: boolean;
23	  isAdmin: boolean;
24	  profile: Profile | null;
25	  /**
26	   * Non-null when either the profile or role fetch failed. Consumers
27	   * can surface a toast/banner; the rest of the app still renders.
28	   */
29	  authError: string | null;
30	  signOut: () => Promise<void>;
31	  refreshProfile: () => Promise<void>;
32	}
33	
34	const AuthContext = createContext<AuthContextType>({
35	  user: null,
36	  session: null,
37	  loading: true,
38	  isAdmin: false,
39	  profile: null,
40	  authError: null,
41	  signOut: async () => {},
42	  refreshProfile: async () => {},
43	});
44	
45	// eslint-disable-next-line react-refresh/only-export-components
46	export const useAuth = () => useContext(AuthContext);
47	
48	export function AuthProvider({ children }: { children: React.ReactNode }) {
49	  const [user, setUser] = useState<User | null>(null);
50	  const [session, setSession] = useState<Session | null>(null);
51	  const [loading, setLoading] = useState(true);
52	  const [isAdmin, setIsAdmin] = useState(false);
53	  const [profile, setProfile] = useState<Profile | null>(null);
54	  const [authError, setAuthError] = useState<string | null>(null);
55	  const userIdRef = useRef<string | null>(null);
56	
57	  const fetchProfile = async (userId: string) => {
58	    try {
59	      const { data, error } = await supabase
60	        .from("profiles")
61	        .select(
62	          "credits, subscription_credits, topup_credits, bonus_credits, inbox_email, plan, email_enabled, auto_rank_enabled, subscription_ends_at",
63	        )
64	        .eq("user_id", userId)
65	        .single();
66	      if (error) throw error;
67	      if (data) {
68	        setProfile(data as Profile);
69	        setAuthError(null);
70	      }
71	    } catch (err) {
72	      console.error("[useAuth] Error fetching profile:", err);
73	      setAuthError(
74	        err instanceof Error
75	          ? `Could not load profile: ${err.message}`
76	          : "Could not load profile",
77	      );
78	    }
79	  };
80	
81	  const fetchRole = async (userId: string) => {
82	    try {
83	      const { data, error } = await supabase
84	        .from("user_roles")
85	        .select("role")
86	        .eq("user_id", userId);
87	      if (error) throw error;
88	      setIsAdmin(
89	        (data ?? []).some((r: { role: string }) => r.role === "admin"),
90	      );
91	    } catch (err) {
92	      console.error("[useAuth] Error fetching role:", err);
93	      // Role fetch failures should NOT silently leave isAdmin=false from
94	      // a previous session — reset it and surface the error so the admin
95	      // panel redirect doesn't look like a bug to the user.
96	      setIsAdmin(false);
97	      setAuthError(
98	        err instanceof Error
99	          ? `Could not verify permissions: ${err.message}`
100	          : "Could not verify permissions",
101	      );
102	    }
103	  };
104	
105	  const refreshProfile = async () => {
106	    if (userIdRef.current) await fetchProfile(userIdRef.current);
107	  };
108	
109	  useEffect(() => {
110	    // Single source of truth: onAuthStateChange fires an INITIAL_SESSION
111	    // event on subscribe, which gives us the current session without a
112	    // separate getSession() call. This eliminates the race where
113	    // getSession() could resolve with null before onAuthStateChange
114	    // caught up, briefly wiping a known-good user state.
115	    const {
116	      data: { subscription },
117	    } = supabase.auth.onAuthStateChange(async (_event, nextSession) => {
118	      setSession(nextSession);
119	      setUser(nextSession?.user ?? null);
120	      userIdRef.current = nextSession?.user?.id ?? null;
121	
122	      if (nextSession?.user) {
123	        // setTimeout avoids the Supabase deadlock inside onAuthStateChange
124	        setTimeout(async () => {
125	          await Promise.all([
126	            fetchProfile(nextSession.user.id),
127	            fetchRole(nextSession.user.id),
128	          ]);
129	        }, 0);
130	      } else {
131	        setProfile(null);
132	        setIsAdmin(false);
133	        setAuthError(null);
134	      }
135	      setLoading(false);
136	    });
137	
138	    return () => subscription.unsubscribe();
139	  }, []);
140	
141	  // Refresh profile on window focus + every 2min to keep credits current
142	  useEffect(() => {
143	    if (!user) return;
144	    const handleFocus = () => fetchProfile(user.id);
145	    window.addEventListener("focus", handleFocus);
146	    const interval = setInterval(() => fetchProfile(user.id), 120_000);
147	    return () => {
148	      window.removeEventListener("focus", handleFocus);
149	      clearInterval(interval);
150	    };
151	    // Intentional: re-run only on user identity change (id), not on every
152	    // Supabase user object reference change. fetchProfile is stable because
153	    // it closes over `supabase` which is a module singleton.
154	    // eslint-disable-next-line react-hooks/exhaustive-deps
155	  }, [user?.id]);
156	
157	  const signOut = async () => {
158	    await supabase.auth.signOut();
159	    setUser(null);
160	    setSession(null);
161	    setProfile(null);
162	    setIsAdmin(false);
163	    setAuthError(null);
164	  };
165	
166	  return (
167	    <AuthContext.Provider
168	      value={{
169	        user,
170	        session,
171	        loading,
172	        isAdmin,
173	        profile,
174	        authError,
175	        signOut,
176	        refreshProfile,
177	      }}
178	    >
179	      {children}
180	    </AuthContext.Provider>
181	  );
182	}
