1	import { createServerClient } from "@supabase/ssr";
2	import { cookies } from "next/headers";
3	import type { Database } from "./types";
4	
5	/**
6	 * Create a request-scoped Supabase server client that reads auth state
7	 * from Next.js cookies. Throws a clear error if the public env vars
8	 * are missing — but only when called, never at module evaluation,
9	 * so `next build` can collect page data even on machines without
10	 * NEXT_PUBLIC_SUPABASE_* set.
11	 */
12	export async function createClient() {
13	  const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
14	  const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
15	
16	  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
17	    throw new Error(
18	      "Missing Supabase environment variables. Set NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in the hosting environment (Railway Variables tab for production, .env.local for local dev).",
19	    );
20	  }
21	
22	  const cookieStore = await cookies();
23	
24	  return createServerClient<Database>(SUPABASE_URL, SUPABASE_ANON_KEY, {
25	    cookies: {
26	      getAll() {
27	        return cookieStore.getAll();
28	      },
29	      setAll(cookiesToSet) {
30	        try {
31	          cookiesToSet.forEach(({ name, value, options }) => {
32	            cookieStore.set(name, value, options);
33	          });
34	        } catch {
35	          // Server Components cannot set cookies. Ignore — middleware
36	          // handles the refresh path and will set cookies on the response.
37	        }
38	      },
39	    },
40	  });
41	}
